import{_ as r,o as e,c as a,a2 as d}from"./chunks/framework.E8pQZ6KS.js";const f=JSON.parse('{"title":"CTF 平台与资源","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/CTF平台与资源.md","filePath":"必学工具/CTF平台与资源.md","lastUpdated":1792430298000}'),o={name:"必学工具/CTF平台与资源.md"};function h(l,t,i,n,c,s){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="ctf-平台与资源" tabindex="-1">CTF 平台与资源 <a class="header-anchor" href="#ctf-平台与资源" aria-label="Permalink to &quot;CTF 平台与资源&quot;">​</a></h1><blockquote><p>CTF（Capture The Flag，夺旗赛）是网安学习的「游戏化课堂」，也是 FAFU 学院「以赛促学」特色的核心载体。这里汇总常用平台与入门资源。</p></blockquote><h2 id="常用在线平台" tabindex="-1">常用在线平台 <a class="header-anchor" href="#常用在线平台" aria-label="Permalink to &quot;常用在线平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>地址</th><th>说明</th></tr></thead><tbody><tr><td>BUUCTF</td><td><a href="https://buuoj.cn/" target="_blank" rel="noreferrer">https://buuoj.cn/</a></td><td>国内最常用的练题平台，题目全、题解多，入门首选</td></tr><tr><td>攻防世界</td><td><a href="https://adworld.xctf.org.cn/" target="_blank" rel="noreferrer">https://adworld.xctf.org.cn/</a></td><td>XCTF 官方平台，含历年真题</td></tr><tr><td>picoCTF</td><td><a href="https://picoctf.org/" target="_blank" rel="noreferrer">https://picoctf.org/</a></td><td>CMU 主办，面向初学者的经典平台，题目友好</td></tr><tr><td>XCTF 社区</td><td><a href="https://xctf.org.cn/" target="_blank" rel="noreferrer">https://xctf.org.cn/</a></td><td>国内 CTF 赛事社区</td></tr><tr><td>CTFtime</td><td><a href="https://ctftime.org/" target="_blank" rel="noreferrer">https://ctftime.org/</a></td><td>全球赛事日历与积分榜</td></tr></tbody></table><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://ctf-wiki.org/" target="_blank" rel="noreferrer">CTF-Wiki</a></td><td>中文 CTF 知识体系（Crypto / Pwn / Reverse / Web / Misc），必读</td></tr><tr><td><a href="https://github.com/ctf-wiki/ctf-challenges" target="_blank" rel="noreferrer">CTF-Archived</a></td><td>CTF-Wiki 配套题库仓库</td></tr><tr><td><a href="https://github.com/search?q=ctf+writeup" target="_blank" rel="noreferrer">GitHub 优质 Writeup 仓库</a></td><td>多看别人的解题思路</td></tr></tbody></table><h2 id="练题方向分工-与课程对应" tabindex="-1">练题方向分工（与课程对应） <a class="header-anchor" href="#练题方向分工-与课程对应" aria-label="Permalink to &quot;练题方向分工（与课程对应）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>对应能力</th><th>关联课程页</th></tr></thead><tbody><tr><td>Crypto</td><td>密码学</td><td><a href="./../安全方向/密码学.html">密码学</a></td></tr><tr><td>Pwn</td><td>二进制利用 / 漏洞</td><td><a href="./../安全方向/二进制安全与逆向.html">二进制安全与逆向</a></td></tr><tr><td>Reverse</td><td>逆向工程</td><td>同上</td></tr><tr><td>Web</td><td>Web 安全</td><td><a href="./../安全方向/Web安全.html">Web 安全</a></td></tr><tr><td>Misc</td><td>综合（流量、取证、隐写等）</td><td><a href="./../安全方向/数字取证.html">数字取证与舆情安全</a></td></tr></tbody></table><h2 id="入门建议" tabindex="-1">入门建议 <a class="header-anchor" href="#入门建议" aria-label="Permalink to &quot;入门建议&quot;">​</a></h2><ol><li><strong>先定方向</strong>：把每个方向的入门题各做几道，找到最感兴趣的一两个；</li><li><strong>以题带学</strong>：不会什么就学什么，看完题解一定自己重做一遍；</li><li><strong>写 Writeup</strong>：每道题写解题记录（放 GitHub），既是复习也是履历；</li><li><strong>组队参赛</strong>：关注 CTFtime 上的线上赛，和同学组队打几场，体验真实节奏（详见 <a href="./../竞赛与成长/CTF与竞赛.html">CTF 与学科竞赛</a>）。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>校内的「以赛促学」氛围浓厚（学院在信息安全类竞赛中获奖众多）。主动找学长学姐组队、问老师要赛题资源，是成长最快的捷径。</p></div>',11)])])}const p=r(o,[["render",h]]);export{f as __pageData,p as default};
